test('keeps display chrome readable with document scrollbars below the min canvas', async ({
  page,
}) => {
  const viewport = {height: 400, width: 360};
  const canvas = getDisplayCanvasSize(viewport, 'vertical');

  await page.setViewportSize(viewport);
  await page.goto('./tvScreenNew/?mock=1&doctors=2');
  await expect(page.locator('.display-screen')).toHaveAttribute('data-orientation', 'vertical');
  await expect(page.locator('.queue-stat-latest dt').first()).toHaveText('最新叫號 Last Call');

  const layout = await page.evaluate(() => {
    const shell = document.querySelector('.display-shell');
    const clinicHeader = document.querySelector('.clinic-header');
    const queueHeader = document.querySelector('.queue-header');
    const lastCallLabels = Array.from(
      document.querySelectorAll('.queue-stat-latest dt, .featured-last-call span'),
    ).map((label) => {
      const rect = label.getBoundingClientRect();

      return {
        bottom: rect.bottom,
        clientWidth: (label as HTMLElement).clientWidth,
        height: rect.height,
        scrollWidth: (label as HTMLElement).scrollWidth,
        text: label.textContent?.trim() ?? '',
        top: rect.top,
      };
    });

    return {
      canvasHeight: shell?.getBoundingClientRect().height ?? 0,
      canvasWidth: shell?.getBoundingClientRect().width ?? 0,
      clinicHeaderBottom: clinicHeader?.getBoundingClientRect().bottom ?? 0,
      documentClientHeight: document.documentElement.clientHeight,
      documentClientWidth: document.documentElement.clientWidth,
      documentScrollHeight: document.documentElement.scrollHeight,
      documentScrollWidth: document.documentElement.scrollWidth,
      lastCallLabels,
      queueHeaderTop: queueHeader?.getBoundingClientRect().top ?? 0,
    };
  });

  expect(layout.canvasWidth).toBeCloseTo(canvas.width, 0);
  expect(layout.canvasHeight).toBeCloseTo(canvas.height, 0);
  expect(layout.documentScrollWidth).toBeGreaterThan(layout.documentClientWidth + 1);
  expect(layout.documentScrollHeight).toBeGreaterThan(layout.documentClientHeight + 1);
  expect(layout.clinicHeaderBottom).toBeLessThanOrEqual(layout.queueHeaderTop + 0.5);
  expect(layout.lastCallLabels.length).toBeGreaterThan(0);
  for (const label of layout.lastCallLabels) {
    expect(label.text).toContain('最新叫號 Last Call');
    expect(label.height).toBeGreaterThan(0);
    expect(label.scrollWidth).toBeLessThanOrEqual(label.clientWidth + 1);
  }
});

test('keeps management chrome readable with document scrollbars below the min canvas', async ({
  page,
}) => {
  const viewport = {height: 400, width: 360};
  const canvas = getPageCanvasSize(viewport, MANAGEMENT_PAGE_MIN_CANVAS);

  await page.addInitScript(() => {
    window.localStorage.setItem('tok', JSON.stringify('local-token'));
    window.localStorage.setItem('userName', JSON.stringify('stark.user'));
    window.localStorage.setItem(
      'userInfo',
      JSON.stringify({
        userName: 'stark.user',
        currentClinic: {
          clinicCode: 'ST',
          clinicEnglishName: 'ST',
        },
      }),
    );
    window.localStorage.setItem('permission', JSON.stringify(['008014']));
    window.localStorage.setItem('locale', JSON.stringify('zh-HK'));
  });
  await mockClinicList(page, [TEST_CLINICS[0]]);
  await page.setViewportSize(viewport);
  await page.goto(MANAGEMENT_ROUTE);
  await expect(page.getByRole('heading', {name: '顯示屏配置', level: 1})).toBeVisible();
  await expect(page.getByRole('button', {name: /新增\s*W/})).toBeVisible();

  const layout = await page.evaluate(() => {
    const shell = document.querySelector('.management-shell');
    const heading = document.querySelector('.management-content-heading h1');
    const addButton = document.querySelector('.management-add-button, .management-content-heading button');
    const headingRect = heading?.getBoundingClientRect();
    const addRect = addButton?.getBoundingClientRect();

    return {
      addBottom: addRect?.bottom ?? 0,
      addHeight: addRect?.height ?? 0,
      canvasHeight: shell?.getBoundingClientRect().height ?? 0,
      canvasWidth: shell?.getBoundingClientRect().width ?? 0,
      documentClientHeight: document.documentElement.clientHeight,
      documentClientWidth: document.documentElement.clientWidth,
      documentScrollHeight: document.documentElement.scrollHeight,
      documentScrollWidth: document.documentElement.scrollWidth,
      headingHeight: headingRect?.height ?? 0,
      headingText: heading?.textContent?.trim() ?? '',
      htmlOverflowX: getComputedStyle(document.documentElement).overflowX,
      htmlOverflowY: getComputedStyle(document.documentElement).overflowY,
    };
  });

  expect(layout.canvasWidth).toBeCloseTo(canvas.width, 0);
  expect(layout.canvasHeight).toBeCloseTo(canvas.height, 0);
  expect(layout.documentScrollWidth).toBeGreaterThan(layout.documentClientWidth + 1);
  expect(layout.documentScrollHeight).toBeGreaterThan(layout.documentClientHeight + 1);
  expect(['auto', 'scroll', 'overlay']).toContain(layout.htmlOverflowX);
  expect(['auto', 'scroll', 'overlay']).toContain(layout.htmlOverflowY);
  expect(layout.headingText).toBe('顯示屏配置');
  expect(layout.headingHeight).toBeGreaterThan(0);
  expect(layout.addHeight).toBeGreaterThan(0);
});

