    shellWidth: shell?.getBoundingClientRect().width ?? null,
    shellHeight: shell?.getBoundingClientRect().height ?? null,
    sidebarLeft: sidebarRect?.left ?? null,
    sidebarTop: sidebarRect?.top ?? null,
    contentLeft: contentRect?.left ?? null,
    contentTop: contentRect?.top ?? null,
    scrollWidth: document.documentElement.scrollWidth,
    scrollHeight: document.documentElement.scrollHeight,
    clientWidth: document.documentElement.clientWidth,
    clientHeight: document.documentElement.clientHeight,
    sidebarStillLeft: (sidebarRect?.left ?? 0) < (contentRect?.left ?? 0) - 1,
    topsAligned: Math.abs((sidebarRect?.top ?? 0) - (contentRect?.top ?? 0)) <= 1,
  };
}

() => {
  const shell = document.querySelector('.display-shell');
  const screen = document.querySelector('.display-screen');
  const waiting = document.querySelector('.queue-stat-waiting-count');
  const waitingLabel = document.querySelector('.queue-stat-waiting');
  return {
    hasDisplayShell: Boolean(shell),
    hasManagementShell: Boolean(document.querySelector('.management-shell')),
    orientation: screen?.className ?? null,
    shellWidth: shell?.getBoundingClientRect().width ?? null,
    shellHeight: shell?.getBoundingClientRect().height ?? null,
    innerWidth: window.innerWidth,
    innerHeight: window.innerHeight,
    scrollWidth: document.documentElement.scrollWidth,
    scrollHeight: document.documentElement.scrollHeight,
    clientWidth: document.documentElement.clientWidth,
    clientHeight: document.documentElement.clientHeight,
    waitingAlign: waiting ? getComputedStyle(waiting).alignItems : null,
    waitingDirection: waiting ? getComputedStyle(waiting).flexDirection : null,
  };
}

() => {
  const shell = document.querySelector('.management-shell');
  const sidebar = document.querySelector('.management-sidebar');
  const content = document.querySelector('.management-content-card');
  const sidebarRect = sidebar?.getBoundingClientRect();
  const contentRect = content?.getBoundingClientRect();
  return {
    innerWidth: window.innerWidth,
    innerHeight: window.innerHeight,
    shellWidth: shell?.getBoundingClientRect().width ?? null,
    shellHeight: shell?.getBoundingClientRect().height ?? null,
    sidebarLeft: sidebarRect?.left ?? null,
    contentLeft: contentRect?.left ?? null,
    scrollWidth: document.documentElement.scrollWidth,
    scrollHeight: document.documentElement.scrollHeight,
    clientWidth: document.documentElement.clientWidth,
    clientHeight: document.documentElement.clientHeight,
    hasHScroll: document.documentElement.scrollWidth > document.documentElement.clientWidth + 1,
    hasVScroll: document.documentElement.scrollHeight > document.documentElement.clientHeight + 1,
  };
}
